package com.dragonkey.monitor;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.io.*;
public class MainActivity extends Activity {
 LinearLayout root; TextView status; int blue=0xff00baff;
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(18,16,18,16);return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff075b9b));b.setOnClickListener(v->r.run());root.addView(b);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,20,24,24);root.setBackgroundColor(0xff03060e);sc.addView(root);setContentView(sc);ImageView img=new ImageView(this);img.setImageResource(com.dragonkey.monitor.R.drawable.dragon);img.setScaleType(ImageView.ScaleType.CENTER_CROP);root.addView(img,new LinearLayout.LayoutParams(-1,180));TextView title=text("DRAGON KEY MONITOR",24);title.setTypeface(null,Typeface.BOLD);title.setTextColor(blue);root.addView(title);root.addView(text("Teclado pessoal • Registro voluntário • Sem coleta de senhas",14));status=text("",16);root.addView(status);button("Ativar / desativar registro",()->{boolean next=!getPreferences(0).getBoolean("record",false);getPreferences(0).edit().putBoolean("record",next).apply();update();});button("Configurar teclado Android",()->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showInputMethodPicker();});button("Ver histórico",()->{try{File f=new File(getFilesDir(),"history.txt");String s="";if(f.exists()){byte[] data=new byte[(int)Math.min(f.length(),100000)];try(FileInputStream in=new FileInputStream(f)){int n=in.read(data);if(n>0)s=new String(data,0,n,java.nio.charset.StandardCharsets.UTF_8);}}new AlertDialog.Builder(this).setTitle("Histórico local").setMessage(s.isEmpty()?"Sem registros":s).setPositiveButton("OK",null).show();}catch(Exception e){Toast.makeText(this,"Erro ao abrir histórico",0).show();}});button("Compartilhar histórico TXT",()->{try{File f=new File(getFilesDir(),"history.txt");if(!f.exists())return;byte[] data=java.nio.file.Files.readAllBytes(f.toPath());Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,new String(data,java.nio.charset.StandardCharsets.UTF_8));startActivity(Intent.createChooser(i,"Exportar histórico"));}catch(Exception e){Toast.makeText(this,"Falha ao exportar",0).show();}});button("Apagar histórico",()->new AlertDialog.Builder(this).setTitle("Apagar tudo?").setPositiveButton("Apagar",(d,w)->{new File(getFilesDir(),"history.txt").delete();Toast.makeText(this,"Histórico apagado",0).show();}).setNegativeButton("Cancelar",null).show());root.addView(text("O registro só funciona enquanto este teclado estiver selecionado e a opção estiver ativa. Campos de senha e entradas sensíveis não são registrados.",13));update();}
 void update(){status.setText("Registro: "+(getPreferences(0).getBoolean("record",false)?"ATIVO":"DESATIVADO"));}
}
